The reconstruction is exact (correlation 1.0000, errors ≤ 0.013), so the per-layer MLP inputs are trustworthy. Next I'll see what switches each detector on. For each of the five neurons I'll print the median gate pre-activation z_g and up value z_u in each region:
- the prompt;
- normal thinking;
- the synthetic loop copies;
- copied prose answers (A);
- non-copied prose answers (B);
- code and math answers.

If the gate is the switch (negative normally, positive during repetition), a negative term added to the gate only inside the answer will turn the detector off there and leave thinking untouched.

```python
# Hypothesis: gate pre-activation z_g is the on/off switch (negative in normal text, positive in loops and copied answers).
def region_masks(i, cat, n, p0, te):
    m = {}
    m['prompt'] = np.arange(n) < p0
    if cat=='E':
        s = next(s for s in synth if s['id']==meta2[i][1]); b0 = s['base_len']; bl = s['blk_tokens']
        m['think'] = (np.arange(n)>=p0)&(np.arange(n)<b0); m['loop23'] = (np.arange(n)>=b0+bl)&(np.arange(n)<n)
    else:
        m['think'] = (np.arange(n)>=p0)&(np.arange(n)<te); m['ans_'+cat] = (np.arange(n)>te)&(np.arange(n)<n-1)
    return m
stats = {}
for i,(cat,iid) in enumerate(meta2):
    n,p0,te = regions(i); masks = region_masks(i,cat,n,p0,te)
    for l in [10,13,14]:
        xt = mlp_in(i,l,n)
        for (ll,nn,_) in DET:
            if ll!=l: continue
            zg = (xt@WG[l][nn]).numpy(); zu = (xt@WU[l][nn]).numpy()
            for r,mk in masks.items():
                stats.setdefault((l,nn,r),[]).append(np.stack([zg[mk], zu[mk]],1))
print('median (z_gate, z_up) per region')
regs = ['prompt','think','loop23','ans_A','ans_B','ans_C','ans_D']
print('neuron      ' + ''.join(f'{r:>15s}' for r in regs))
for (l,nn,_) in DET:
    s = ''
    for r in regs:
        v = np.concatenate(stats.get((l,nn,r),[np.zeros((0,2))]))
        s += f'  {np.median(v[:,0]):6.2f},{np.median(v[:,1]):6.2f}' if len(v) else ' '*15
    print(f'L{l} n{nn:<5d}' + s)
